command:
set -euo pipefail
export PATH=/opt/conda/bin:$PATH
export TMPDIR=/tmp HOME=/tmp
cd /tmp

RV=$(rsem-calculate-expression --version 2>&1 | awk 'NR==1{print $NF}')
echo "== two transcripts sharing an 800 bp block, with unique regions of very different length =="
awk 'function r(n,  s,i){ s=""; for(i=0;i<n;i++) s=s substr(B,int(rand()*4)+1,1); return s }
BEGIN{ srand(67); B="ACGT"
  S=r(800); uA=r(100); uB=r(800)
  printf ">txA\n%s\n>txB\n%s\n", uA S, uB S > "txome.fa"
}'
awk '/^>/{n=substr($0,2); next} {printf "fixture_%s\t%d bp\n", n, length($0)}' txome.fa | tee fixture.txt
LA=$(awk '/^>txA/{getline; print length($0)}' txome.fa)
LB=$(awk '/^>txB/{getline; print length($0)}' txome.fa)
test "$LA" = "900"  || { echo "txA is $LA bp, expected 900"; exit 1; }
test "$LB" = "1600" || { echo "txB is $LB bp, expected 1600"; exit 1; }

echo "== 1500 reads from txA and 500 from txB: a planted READ ratio of exactly 3 =="
awk 'BEGIN{
  while ((getline l < "txome.fa") > 0) { if (l ~ /^>/) nm=substr(l,2); else seq[nm]=l }
  RL=100; q=""; for(i=0;i<RL;i++) q=q "I"
  split("txA 1500 txB 500", a, " ")
  n=0
  for(k=1;k<=3;k+=2){
    t=a[k]; N=a[k+1]+0; L=length(seq[t]); starts=L-RL+1
    for(i=0;i<N;i++){ p = 1 + (i*3) % starts
      n++; printf "@%s_r%d\n%s\n+\n%s\n", t, i+1, substr(seq[t],p,RL), q > "reads.fq" }
    printf "%s\t%d\n", t, N > "truth.tsv"
  }
  printf "fixture_reads\t%d total\n", n
}' | tee -a fixture.txt
NR_=$(awk 'END{print NR/4}' reads.fq)
PT=$(awk '{n+=$2} END{print n}' truth.tsv)
test "$NR_" = "$PT" || { echo "wrote $NR_ reads, planted $PT"; exit 1; }
PA=$(awk '$1=="txA"{print $2}' truth.tsv); PB=$(awk '$1=="txB"{print $2}' truth.tsv)
awk -v a="$PA" -v b="$PB" 'BEGIN{ r=a/b; if (r < 2.999 || r > 3.001) { printf "planted ratio %.4f, expected 3\n", r; exit 1 }
  printf "planted_ratio\t%.1f  (txA:txB by READ COUNT)\n", r }' | tee -a fixture.txt

echo "== RSEM reference (no aligner needed for this step) =="
rsem-prepare-reference txome.fa idx > prep.log 2>&1 || { tail -15 prep.log; exit 1; }
ls idx.* | tr '\n' ' '; echo
NSEQ=$(awk '/^>/{n++} END{print n+0}' idx.transcripts.fa)
test "$NSEQ" = "2" || { echo "reference has $NSEQ transcripts, expected 2"; exit 1; }
{ printf 'rsem_version\t%s\n' "$RV"
  printf 'reference_transcripts\t%s   (assert 2)\n' "$NSEQ"; } | tee -a fixture.txt
echo "REFERENCE OK"
